import subprocess
import os
import ctypes
import tempfile
import queue
import re
import threading
from io import BytesIO
import tkinter as tk
from tkinter import ttk, messagebox, filedialog
import base64
from PIL import Image
ICON_BASE64 = """

"""

if os.name == "nt":
    ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(
        "yt-dlp.custom-downloader"
    )

root = tk.Tk()

# Convert base64 string to an image object
app_icon = tk.PhotoImage(data=ICON_BASE64)

# Windows taskbar icons use an ICO resource rather than Tk's PNG image data.
icon_file_descriptor, icon_path = tempfile.mkstemp(suffix=".ico")
os.close(icon_file_descriptor)
with Image.open(BytesIO(base64.b64decode(ICON_BASE64))) as icon_image:
    icon_image.save(
        icon_path,
        format="ICO",
        sizes=[(16, 16), (32, 32), (48, 48), (256, 256)],
    )

# Set both the Tk window icon and the Windows taskbar icon.
root.iconphoto(True, app_icon)
root.iconbitmap(icon_path)


def remove_icon_file():
    if os.path.exists(icon_path):
        os.remove(icon_path)


root.protocol("WM_DELETE_WINDOW", lambda: (remove_icon_file(), root.destroy()))

worker_queue = queue.Queue()
download_process = None

def select_folder():
    selected_dir = filedialog.askdirectory()
    if selected_dir:
        folder_var.set(selected_dir)

def show_download_options():
    ytlink = entry_link.get().strip()
    if not ytlink:
        messagebox.showerror("Error", "Please paste a link first!")
        return

    btn_next.config(state="disabled", text="Loading...")
    threading.Thread(target=fetch_video_info, args=(ytlink,), daemon=True).start()

def fetch_video_info(ytlink):
    command = ["yt-dlp", "--flat-playlist", "--print", "%(title)s", ytlink]
    if not playlist_var.get():
        command.insert(1, "--no-playlist")
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=120)
        titles = [line.strip() for line in result.stdout.splitlines() if line.strip()]
        worker_queue.put(("info_done", result.returncode, titles, result.stderr))
    except (OSError, subprocess.TimeoutExpired) as error:
        worker_queue.put(("info_error", str(error)))

def poll_worker_queue():
    try:
        while True:
            event = worker_queue.get_nowait()
            handle_worker_event(event)
    except queue.Empty:
        pass
    root.after(100, poll_worker_queue)

def handle_worker_event(event):
    event_type = event[0]
    if event_type == "info_done":
        _, returncode, titles, error_text = event
        btn_next.config(state="normal", text="Next")
        if returncode != 0:
            messagebox.showerror("Error", f"Could not read video information:\n{error_text}")
            return
        if playlist_var.get() and len(titles) > 1:
            video_title_var.set(f"Playlist: {titles[0]}\n{len(titles)} videos found")
        else:
            video_title_var.set(titles[0] if titles else "Untitled video")
        link_panel.pack_forget()
        options_panel.pack(fill="x", padx=20, pady=10)
    elif event_type == "info_error":
        btn_next.config(state="normal", text="Next")
        messagebox.showerror("Error", f"Could not fetch video information:\n{event[1]}")
    elif event_type == "progress":
        _, percent, status = event
        progress_var.set(percent)
        progress_label_var.set(f"{percent:.1f}%  {status}")
        if advanced_var.get():
            append_status(status)
    elif event_type == "output":
        if advanced_var.get():
            append_status(event[1])
    elif event_type == "download_done":
        _, returncode, error_text = event
        btn_download.config(state="normal", text="Download")
        btn_back.config(state="normal")
        if returncode == 0:
            progress_var.set(100)
            progress_label_var.set("100.0%  Complete")
            messagebox.showinfo("Success", "Download complete!")
        else:
            messagebox.showerror("Error", f"Download failed:\n{error_text}")

def append_status(text):
    status_text.config(state="normal")
    status_text.insert("end", text + "\n")
    status_text.see("end")
    status_text.config(state="disabled")

def toggle_advanced_status():
    if advanced_var.get():
        advanced_frame.pack(fill="x", pady=(8, 0))
    else:
        advanced_frame.pack_forget()

def build_download_command(ytlink, save_dir):
    output_template = os.path.join(save_dir, "%(title)s.%(ext)s")
    cmd = ["yt-dlp", "--newline", "--progress", "-o", output_template, ytlink]
    if not playlist_var.get():
        cmd.insert(1, "--no-playlist")

    quality_choice = quality_var.get()
    if quality_choice == "Best":
        cmd.extend(["-f", "bv*+ba/b"])
    elif quality_choice == "1080p":
        cmd.extend(["-f", "bestvideo[height<=1080]+bestaudio/best[height<=1080]"])
    elif quality_choice == "720p":
        cmd.extend(["-f", "bestvideo[height<=720]+bestaudio/best[height<=720]"])
    elif quality_choice == "480p":
        cmd.extend(["-f", "bestvideo[height<=480]+bestaudio/best[height<=480]"])
    elif quality_choice == "Audio Only (Best)":
        cmd.extend(["-x", "--audio-format", "mp3", "--audio-quality", "0"])
    elif quality_choice == "Audio Only (Low Size)":
        cmd.extend(["-x", "--audio-format", "mp3", "--audio-quality", "9"])

    caption_choice = caption_var.get()
    if caption_choice == "English subtitles":
        cmd.extend(["--write-subs", "--sub-langs", "en"])
    elif caption_choice == "Auto-generated subtitles":
        cmd.extend(["--write-auto-subs", "--sub-langs", "en"])
    if embed_captions_var.get() and caption_choice != "None":
        cmd.append("--embed-subs")
    return cmd

def download_video():
    ytlink = entry_link.get().strip()
    save_dir = folder_var.get()
    
    if not ytlink:
        messagebox.showerror("Error", "Please paste a link first!")
        return

    if not save_dir:
        messagebox.showerror("Error", "Please select a download folder!")
        return

    btn_download.config(state="disabled", text="Downloading...")
    btn_back.config(state="disabled")
    progress_var.set(0)
    progress_label_var.set("Starting download...")
    status_text.config(state="normal")
    status_text.delete("1.0", "end")
    status_text.config(state="disabled")
    command = build_download_command(ytlink, save_dir)
    threading.Thread(target=run_download, args=(command,), daemon=True).start()

def run_download(command):
    global download_process
    try:
        download_process = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        last_output = ""
        for line in download_process.stdout:
            output = line.strip()
            if not output:
                continue
            last_output = output
            match = re.search(r"(\d+(?:\.\d+)?)%", output)
            if match:
                worker_queue.put(("progress", float(match.group(1)), output))
            else:
                worker_queue.put(("output", output))
        returncode = download_process.wait()
        worker_queue.put(("download_done", returncode, last_output))
    except OSError as error:
        worker_queue.put(("download_done", 1, str(error)))
    finally:
        download_process = None

def edit_link():
    options_panel.pack_forget()
    link_panel.pack(fill="x", padx=20, pady=10)

# --- Color Palette (Dark Lime) ---
