btn_next = tk.Button(link_panel, text="Next", command=show_download_options, bg=LIME_ACCENT, fg=DARK_TEXT, font=("Arial", 11, "bold"), relief="flat", activebackground=LIME_HOVER, activeforeground=DARK_TEXT, cursor="hand2")
btn_next.pack(pady=15, ipadx=20, ipady=4)

options_panel = tk.Frame(root, bg=BG_COLOR)
video_title_var = tk.StringVar(value="")
tk.Label(options_panel, textvariable=video_title_var, bg=BG_COLOR, fg=LIME_ACCENT, font=("Arial", 12, "bold"), wraplength=430).pack(pady=(5, 12))

label_folder = tk.Label(options_panel, text="Save Destination:", bg=BG_COLOR, fg=TEXT_COLOR, font=("Arial", 10, "bold"))
label_folder.pack(pady=(0, 2))

folder_frame = tk.Frame(options_panel, bg=BG_COLOR)
folder_frame.pack(pady=2)

folder_var = tk.StringVar(value=os.path.expanduser("~/Downloads"))
entry_folder = tk.Entry(folder_frame, textvariable=folder_var, width=37, bg=INPUT_BG, fg=TEXT_COLOR, insertbackground=LIME_ACCENT, relief="flat", font=("Arial", 9))
entry_folder.pack(side="left", ipady=3, padx=(0, 5))

btn_browse = tk.Button(folder_frame, text="Browse...", command=select_folder, bg=INPUT_BG, fg=LIME_ACCENT, font=("Arial", 9, "bold"), relief="flat", activebackground=LIME_ACCENT, activeforeground=DARK_TEXT, cursor="hand2")
btn_browse.pack(side="right")

label_quality = tk.Label(options_panel, text="Quality / Format:", bg=BG_COLOR, fg=TEXT_COLOR, font=("Arial", 10, "bold"))
label_quality.pack(pady=(10, 2))

quality_var = tk.StringVar(value="Best")
quality_options = ["Best", "1080p", "720p", "480p", "Audio Only (Best)", "Audio Only (Low Size)"]
